const ex = [
 [["S","Ch","Or"],2],
 [["S","Ch","Or","Z","H"],3],
 [["S","Ch","Or","Z","H","Cy"],5],
 [["S","S","Ch","Or"],4],
 [["S","S","Ch","Or","Z"],6],
 [["S","Cy"],2],
 [["S","UW","UW","Ch"],2],
 [["S","UW","UW","UW","Cy","Or","Ch"],3],
 [["S","Ch","Ch","Ch","Or","Or"],2],
 [["Ch","Or","Z"],0],
];
for (const [a,exp] of ex) {
  const n = a.filter(x=>x==="S").length;
  const types = new Set(a).size;
  const per = n? exp/n : null;
  console.log(a.join(",").padEnd(34), "sphinx="+n, "types="+types, "cards="+a.length, "per="+per);
}
EOF
node /tmp/scratch.mjs

cat > /tmp/s2.mjs <<'EOF'
const ex = [
 [["S","Ch","Or"],2],[["S","Ch","Or","Z","H"],3],[["S","Ch","Or","Z","H","Cy"],5],
 [["S","S","Ch","Or"],4],[["S","S","Ch","Or","Z"],6],[["S","Cy"],2],
 [["S","UW","UW","Ch"],2],[["S","UW","UW","UW","Cy","Or","Ch"],3],
 [["S","Ch","Ch","Ch","Or","Or"],2],[["Ch","Or","Z"],0],
];
// hypothesis: t = distinct types among OTHER cards (self excluded, duplicates of sphinx still count as type)
for (const [a,exp] of ex) {
  let total=0;
  a.forEach((c,i)=>{ if(c!=="S") return;
    const others = a.filter((_,j)=>j!==i);
    const t = new Set(others).size;
    total += t>3 ? 2*(t-3) : 1;
  });
  console.log(a.join(",").padEnd(30), "got",total,"exp",exp, total===exp?"OK":"XX");
}
EOF
node /tmp/s2.mjs

cat > /tmp/s3.mjs <<'EOF'
const ex = [
 [["S","Ch","Or"],2],[["S","Ch","Or","Z","H"],3],[["S","Ch","Or","Z","H","Cy"],5],
 [["S","S","Ch","Or"],4],[["S","S","Ch","Or","Z"],6],[["S","Cy"],2],
 [["S","UW","UW","Ch"],2],[["S","UW","UW","UW","Cy","Or","Ch"],3],
 [["S","Ch","Ch","Ch","Or","Or"],2],[["Ch","Or","Z"],0],
];
const variants = {
  "self-excluded, base1": (a)=>{let t=0;a.forEach((c,i)=>{if(c!=="S")return;const n=new Set(a.filter((_,j)=>j!==i)).size;t+=1+(n>3?2*(n-3):1);});return t;},
  "all types, base1":     (a)=>{const n=new Set(a).size;return a.filter(c=>c==="S").length*(1+(n>3?2*(n-3):1));},
};
for (const [name,f] of Object.entries(variants)) {
  let ok=0; const bad=[];
  for (const [a,exp] of ex){ const g=f(a); if(g===exp) ok++; else bad.push(a.join(",")+" got"+g+" exp"+exp); }
  console.log(name, ok+"/"+ex.length, bad.join(" | "));
}
EOF
node /tmp/s3.mjs

