import { describe, it, expect } from "vitest";
import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx scoring", () => {
  // No Sphinx
  it.todo("scores an army with no Sphinx as 0 — Chimera, Orthrus, Zombie → 0");

  // "…else 1" — at or below three types, the bonus is a flat 1
  it.todo("scores a lone Sphinx with one other type as 2 — Sphinx, Cyclops → 2");
  it.todo("scores a Sphinx with three types in the army as 2 — Sphinx, Chimera, Orthrus → 2");

  // Duplicate cards of the same monster collapse to one type
  it.todo("ignores duplicate cards of the same monster — Sphinx, Chimera x3, Orthrus x2 → 2");

  // Beyond three types: 2 per type beyond three, on top of the base point
  it.todo("scores 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3");
  it.todo("scores 2 per type beyond three for a wider army — Sphinx, Chimera, Orthrus, Zombie, Hydra, Cyclops → 5");

  // A Sphinx does not count itself, but does count another Sphinx
  it.todo("does not count itself towards its own types — Sphinx, Sphinx, Chimera, Orthrus → 4");
  it.todo("counts the other Sphinx towards types — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6");

  // Undead Warrior variants are one type
  it.todo("treats Undead Warrior variants as one type — Sphinx, Undead Warrior (1), Undead Warrior (3), Chimera → 2");
  it.todo("treats all three Undead Warrior variants as one type — Sphinx, UW (1), UW (2), UW (3), Cyclops, Orthrus, Chimera → 3");
});

